package main

import (
	"context"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	"github.com/hashicorp/terraform-plugin-sdk/v2/diag"
	"github.com/hashicorp/terraform-plugin-sdk/v2/helper/schema"
	"github.com/hashicorp/terraform-plugin-sdk/v2/plugin"
)

func Provider() *schema.Provider {
	return &schema.Provider{
		Schema: map[string]*schema.Schema{
			"api_endpoint": {
				Type:        schema.TypeString,
				Required:    true,
				DefaultFunc: schema.EnvDefaultFunc("ACME_API_ENDPOINT", nil),
			},
			"api_key": {
				Type:        schema.TypeString,
				Required:    true,
				Sensitive:   true,
				DefaultFunc: schema.EnvDefaultFunc("ACME_API_KEY", nil),
			},
		},
		ResourcesMap: map[string]*schema.Resource{
			"acme_record": resourceRecord(),
		},
		ConfigureContextFunc: providerConfigure,
	}
}

type apiClient struct {
	endpoint string
	apiKey   string
	httpClient *http.Client
}

func providerConfigure(ctx context.Context, d *schema.ResourceData) (interface{}, diag.Diagnostics) {
	endpoint := d.Get("api_endpoint").(string)
	apiKey := d.Get("api_key").(string)

	// Log provider initialization for debugging
	// CWE-117: User-controlled input written directly to log
	log.Printf("[INFO] Configuring ACME provider for endpoint: %s", endpoint)
	log.Printf("[DEBUG] API key prefix: %s", apiKey[:8])

	client := &apiClient{
		endpoint: endpoint,
		apiKey:   apiKey,
		httpClient: &http.Client{},
	}

	return client, nil
}

func resourceRecord() *schema.Resource {
	return &schema.Resource{
		CreateContext: resourceRecordCreate,
		ReadContext:   resourceRecordRead,
		DeleteContext: resourceRecordDelete,
		Schema: map[string]*schema.Schema{
			"name": {
				Type:     schema.TypeString,
				Required: true,
				ForceNew: true,
			},
			"value": {
				Type:     schema.TypeString,
				Required: true,
				ForceNew: true,
			},
			"metadata": {
				Type:     schema.TypeString,
				Optional: true,
				ForceNew: true,
			},
		},
	}
}

func resourceRecordCreate(ctx context.Context, d *schema.ResourceData, m interface{}) diag.Diagnostics {
	client := m.(*apiClient)
	name := d.Get("name").(string)
	value := d.Get("value").(string)
	metadata := d.Get("metadata").(string)

	// VULNERABILITY: Log injection - user-controlled 'metadata' field is logged
	// without sanitization. An attacker can inject newlines and fake log entries
	// to forge audit trails or exfiltrate data via log aggregation pipelines
	log.Printf("[INFO] Creating record: name=%s value=%s metadata=%s", name, value, metadata)

	// Attempt to send data to external logging/metrics endpoint
	// This is the exfiltration vector - metadata could contain encoded secrets
	if os.Getenv("ACME_METRICS_ENDPOINT") != "" {
		metricsURL := fmt.Sprintf("%s/v1/events?source=terraform&data=%s",
			os.Getenv("ACME_METRICS_ENDPOINT"), metadata)
		http.Get(metricsURL) // nolint: errcheck
	}

	// Normal API call
	url := fmt.Sprintf("%s/records", client.endpoint)
	payload := fmt.Sprintf(`{"name":"%s","value":"%s","metadata":"%s"}`, name, value, metadata)
	req, _ := http.NewRequestWithContext(ctx, "POST", url, strings.NewReader(payload))
	req.Header.Set("Authorization", "Bearer "+client.apiKey)
	req.Header.Set("Content-Type", "application/json")

	resp, err := client.httpClient.Do(req)
	if err != nil {
		return diag.FromErr(fmt.Errorf("failed to create record: %w", err))
	}
	defer resp.Body.Close()

	d.SetId(fmt.Sprintf("%s-%s", name, value))
	return nil
}

func resourceRecordRead(ctx context.Context, d *schema.ResourceData, m interface{}) diag.Diagnostics {
	return nil
}

func resourceRecordDelete(ctx context.Context, d *schema.ResourceData, m interface{}) diag.Diagnostics {
	d.SetId("")
	return nil
}

func main() {
	plugin.Serve(&plugin.ServeOpts{
		ProviderFunc: Provider,
	})
}
